function ProgressBar({ progress, color }: { progress: number; color: string }) {
  return (
    <View style={styles.progressBg}>
      <View style={[styles.progressFill, { width: `${progress}%` as any, backgroundColor: color }]} />
    </View>
  );
}

function CourseCard({ course, onEnroll }: { course: any; onEnroll: (id: string) => void }) {
  return (
    <Pressable
      style={({ pressed }) => [styles.courseCard, { opacity: pressed ? 0.88 : 1 }]}
      onPress={() => Haptics.selectionAsync()}
    >
      <View style={[styles.courseIconWrap, { backgroundColor: course.color + "22" }]}>
        <Ionicons name={course.icon as any} size={26} color={course.color} />
      </View>
      <View style={{ flex: 1, gap: 6 }}>
        <View style={styles.courseHeader}>
          <Text style={styles.courseTitle} numberOfLines={2}>{course.title}</Text>
          {course.completed && (
            <View style={styles.completedBadge}>
              <Ionicons name="checkmark-circle" size={14} color={C.SUCCESS} />
              <Text style={styles.completedText}>Done</Text>
            </View>
          )}
        </View>
        <View style={styles.courseMeta}>
          <Ionicons name="person-outline" size={12} color={C.TEXT_SECONDARY} />
          <Text style={styles.courseInstructor}>{course.instructor}</Text>
        </View>
        <View style={styles.courseMeta}>
          <Ionicons name="time-outline" size={12} color={C.TEXT_SECONDARY} />
          <Text style={styles.courseDuration}>{course.duration} · {course.lessons} lessons</Text>
          <View style={styles.dot} />
          <Ionicons name="people-outline" size={12} color={C.TEXT_SECONDARY} />
          <Text style={styles.courseDuration}>{course.attendees}</Text>
        </View>
        {course.enrolled && !course.completed && (
          <View style={{ gap: 4 }}>
            <View style={styles.progressRow}>
              <Text style={styles.progressLabel}>Progress</Text>
              <Text style={[styles.progressPct, { color: course.color }]}>{course.progress}%</Text>
            </View>
            <ProgressBar progress={course.progress} color={course.color} />
          </View>
        )}
        {!course.enrolled && (
          <View style={styles.actionRow}>
            <Pressable
              style={({ pressed }) => [styles.enrollBtn, { borderColor: course.color, opacity: pressed ? 0.8 : 1 }]}
              onPress={() => {
                Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
                onEnroll(course.id);
              }}
            >
              <Text style={[styles.enrollText, { color: course.color }]}>Enroll Now</Text>
            </Pressable>
            <Text style={styles.discountHint}>-25% via Sponsor</Text>
          </View>
        )}
      </View>
    </Pressable>
  );
}

export default function CoursesScreen() {
  const insets = useSafeAreaInsets();
  const [filter, setFilter] = useState("All");
  const [courses, setCourses] = useState(COURSES);

  const topPad = insets.top + (Platform.OS === "web" ? 67 : 0);

  const handleEnroll = (id: string) => {
    setCourses((prev) =>
      prev.map((c) => (c.id === id ? { ...c, enrolled: true } : c))
    );
  };

  const filtered = courses.filter((c) => {
    if (filter === "Enrolled") return c.enrolled && !c.completed;
    if (filter === "Available") return !c.enrolled;
    if (filter === "Completed") return c.completed;
    return true;
  });

  const enrolledCount = courses.filter((c) => c.enrolled).length;
  const completedCount = courses.filter((c) => c.completed).length;
  const avgProgress = Math.round(
    courses.filter((c) => c.enrolled).reduce((sum, c) => sum + c.progress, 0) / Math.max(enrolledCount, 1)
  );

  return (
    <View style={styles.screen}>
      <ScrollView
        contentContainerStyle={{ paddingBottom: 140 }}
        showsVerticalScrollIndicator={false}
        contentInsetAdjustmentBehavior="automatic"
      >
        <LinearGradient
          colors={[C.NAVY, "#101630"]}
          style={[styles.header, { paddingTop: topPad + 16 }]}
        >
          <Text style={styles.headerTitle}>My Courses</Text>
          <Text style={styles.headerSubtitle}>Proud Pakistani Learning Portal</Text>
          <View style={styles.summaryRow}>
            <View style={styles.summaryItem}>
              <Text style={styles.summaryValue}>{enrolledCount}</Text>
              <Text style={styles.summaryLabel}>Enrolled</Text>
            </View>
            <View style={styles.summaryDivider} />
            <View style={styles.summaryItem}>
              <Text style={styles.summaryValue}>{completedCount}</Text>
              <Text style={styles.summaryLabel}>Completed</Text>
            </View>
            <View style={styles.summaryDivider} />
            <View style={styles.summaryItem}>
              <Text style={[styles.summaryValue, { color: C.GOLD }]}>{avgProgress}%</Text>
              <Text style={styles.summaryLabel}>Avg Progress</Text>
            </View>
          </View>
        </LinearGradient>

        <View style={styles.filterRow}>
          {FILTERS.map((f) => (
            <Pressable
              key={f}
              style={[styles.filterBtn, filter === f && styles.filterActive]}
              onPress={() => {
                setFilter(f);
                Haptics.selectionAsync();
              }}
            >
              <Text style={[styles.filterText, filter === f && styles.filterTextActive]}>{f}</Text>
            </Pressable>
          ))}
        </View>

        <View style={styles.list}>
          {filtered.length === 0 ? (
            <View style={styles.empty}>
              <Ionicons name="book-outline" size={48} color={C.TEXT_SECONDARY} />
              <Text style={styles.emptyText}>No courses in this category</Text>
            </View>
          ) : (
            filtered.map((c) => (
              <CourseCard key={c.id} course={c} onEnroll={handleEnroll} />
            ))
          )}
        </View>

        {/* --- SOCIAL MEDIA FOOTER (NEW ADDITION) --- */}
        <View style={styles.socialSection}>
          <Text style={styles.socialTitle}>Official Proud Pakistani Channels</Text>
          <View style={styles.socialIcons}>
            <Pressable onPress={() => Linking.openURL('https://www.instagram.com/proud_pakistani_company')} style={styles.socialBtn}>
              <Ionicons name="logo-instagram" size={24} color="#E1306C" />
            </Pressable>
            <Pressable onPress={() => Linking.openURL('https://www.youtube.com/@proud_pakistani_company')} style={styles.socialBtn}>
              <Ionicons name="logo-youtube" size={24} color="#FF0000" />
            </Pressable>
            <Pressable onPress={() => Linking.openURL('https://www.facebook.com/profile.php?id=61573696611305')} style={styles.socialBtn}>
              <Ionicons name="logo-facebook" size={24} color="#1877F2" />
            </Pressable>
            <Pressable onPress={() => Linking.openURL('https://wa.me/message/BZPN5GMP7ZYEH1')} style={styles.socialBtn}>
              <Ionicons name="logo-whatsapp" size={24} color="#25D366" />
            </Pressable>
          </View>
        </View>

      </ScrollView>
    </View>
  );
}

