function AnimatedStatCard({ label, value, icon, color, index }: any) {
  const scale = useRef(new Animated.Value(1)).current;
  const onPressIn = () => {
    Animated.spring(scale, { toValue: 0.94, useNativeDriver: true, speed: 50 }).start();
    Haptics.selectionAsync();
  };
  const onPressOut = () =>
    Animated.spring(scale, { toValue: 1, useNativeDriver: true }).start();

  return (
    <Pressable onPressIn={onPressIn} onPressOut={onPressOut} style={{ width: "47%" }}>
      <Animated.View style={[styles.statCard, { transform: [{ scale }] }]}>
        <LinearGradient
          colors={[color + "28", color + "08"]}
          style={styles.statGrad}
        >
          <View style={[styles.statIconWrap, { backgroundColor: color + "28" }]}>
            <Ionicons name={icon as any} size={22} color={color} />
          </View>
          <Text style={[styles.statValue, { color }]}>{value}</Text>
          <Text style={styles.statLabel}>{label}</Text>
        </LinearGradient>
      </Animated.View>
    </Pressable>
  );
}

