export default function GalleryScreen() {
  const insets = useSafeAreaInsets();
  const [category, setCategory] = useState("All");
  const [view, setView] = useState<"grid" | "list">("grid");

  const topPad = insets.top + (Platform.OS === "web" ? 67 : 0);

  const filtered = GALLERY_ITEMS.filter(
    (g) => category === "All" || g.category === category
  );

  return (
    <View style={styles.screen}>
      <ScrollView
        contentContainerStyle={{ paddingBottom: 120 }}
        showsVerticalScrollIndicator={false}
        contentInsetAdjustmentBehavior="automatic"
      >
        <LinearGradient
          colors={[C.NAVY, "#101630"]}
          style={[styles.header, { paddingTop: topPad + 16 }]}
        >
          <View style={styles.headerRow}>
            <Text style={styles.headerTitle}>Gallery</Text>
            <Pressable
              style={styles.viewToggle}
              onPress={() => {
                setView(v => v === "grid" ? "list" : "grid");
                Haptics.selectionAsync();
              }}
            >
              <Ionicons
                name={view === "grid" ? "list" : "grid"}
                size={20}
                color={C.GOLD}
              />
            </Pressable>
          </View>

          <ScrollView horizontal showsHorizontalScrollIndicator={false}>
            <View style={styles.highlightsRow}>
              {HIGHLIGHTS.map((h) => (
                <View key={h.label} style={styles.highlightCard}>
                  <View style={[styles.highlightIcon, { backgroundColor: h.color + "22" }]}>
                    <Ionicons name={h.icon as any} size={18} color={h.color} />
                  </View>
                  <Text style={[styles.highlightValue, { color: h.color }]}>{h.value}</Text>
                  <Text style={styles.highlightLabel}>{h.label}</Text>
                </View>
              ))}
            </View>
          </ScrollView>
        </LinearGradient>

        <ScrollView
          horizontal
          showsHorizontalScrollIndicator={false}
          contentContainerStyle={styles.catRow}
        >
          {CATEGORIES.map((c) => (
            <Pressable
              key={c}
              style={[styles.catBtn, category === c && styles.catActive]}
              onPress={() => {
                setCategory(c);
                Haptics.selectionAsync();
              }}
            >
              <Text style={[styles.catText, category === c && styles.catTextActive]}>{c}</Text>
            </Pressable>
          ))}
        </ScrollView>

        <View style={styles.content}>
          {view === "grid" ? (
            <View style={styles.grid}>
              {filtered.map((item) => (
                <Pressable
                  key={item.id}
                  style={({ pressed }) => [
                    styles.gridItem,
                    { opacity: pressed ? 0.85 : 1 },
                  ]}
                  onPress={() => Haptics.selectionAsync()}
                >
                  <LinearGradient
                    colors={[item.color + "44", item.color + "11"]}
                    style={styles.gridGrad}
                  >
                    <Ionicons name={item.icon as any} size={32} color={item.color} />
                    <Text style={styles.gridCat}>{item.category}</Text>
                    <Text style={styles.gridTitle} numberOfLines={2}>{item.title}</Text>
                    <Text style={styles.gridDate}>{item.date}</Text>
                  </LinearGradient>
                </Pressable>
              ))}
            </View>
          ) : (
            <View style={styles.listContainer}>
              {filtered.map((item) => (
                <Pressable
                  key={item.id}
                  style={({ pressed }) => [styles.listItem, { opacity: pressed ? 0.88 : 1 }]}
                  onPress={() => Haptics.selectionAsync()}
                >
                  <View style={[styles.listIconWrap, { backgroundColor: item.color + "22" }]}>
                    <Ionicons name={item.icon as any} size={28} color={item.color} />
                  </View>
                  <View style={{ flex: 1 }}>
                    <View style={styles.listMeta}>
                      <Text style={[styles.listCat, { color: item.color }]}>{item.category}</Text>
                      <Text style={styles.listDate}>{item.date}</Text>
                    </View>
                    <Text style={styles.listTitle}>{item.title}</Text>
                    <Text style={styles.listDesc}>{item.desc}</Text>
                    {item.members > 0 && (
                      <View style={styles.memberRow}>
                        <Ionicons name="people-outline" size={12} color={C.TEXT_SECONDARY} />
                        <Text style={styles.memberText}>{item.members} members</Text>
                      </View>
                    )}
                  </View>
                  <Ionicons name="chevron-forward" size={16} color={C.TEXT_SECONDARY} />
                </Pressable>
              ))}
            </View>
          )}
        </View>
      </ScrollView>
    </View>
  );
}

