import React, { createContext, useContext, useState, useEffect, useMemo, ReactNode } from 'react';
import AsyncStorage from '@react-native-async-storage/async-storage';

export type UserRole = 'user' | 'hod' | 'admin';

export interface User {
  id: string;
  numericId: string;
  name: string;
  role: UserRole;
  department: string;
  affiliateId: string;
  email: string;
  phone: string;
  joinDate: string;
  totalSales: number;
  monthlySales: number;
  rank: string;
  activeWallet: string;
  passiveWallet: string;
  closingWallet: string;
}

interface AuthContextValue {
  user: User | null;
  isLoading: boolean;
  login: (numericId: string, password: string) => Promise<boolean>;
  logout: () => void;
}

const AuthContext = createContext<AuthContextValue | null>(null);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    (async () => {
      try {
        const stored = await AsyncStorage.getItem('@easylife_user');
        if (stored) setUser(JSON.parse(stored));
      } catch {}
      setIsLoading(false);
    })();
  }, []);

  const login = async (numericId: string, password: string): Promise<boolean> => {
    try {
      const response = await fetch('https://easylife.com.pk/api/app-login', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json',
        },
        body: JSON.stringify({
          member_id: numericId,
          password: password,
        }),
      });

      const data = await response.json();

      if (response.ok && data.user) {
        const loggedInUser: User = {
          id: data.user.id.toString(),
          numericId: data.user.member_id,
          name: data.user.name,
          role: (data.user.role || 'user') as UserRole,
          department: data.user.department || 'Sales',
          affiliateId: data.user.affiliate_id || `EL-${data.user.member_id}`,
          email: data.user.email,
          phone: data.user.phone || '',
          joinDate: data.user.join_date || '2025',
          totalSales: Number(data.user.total_sales || 0),
          monthlySales: Number(data.user.monthly_sales || 0),
          rank: data.user.rank || 'Member',
          activeWallet: String(data.user.active_wallet || '0.00'),
          passiveWallet: String(data.user.passive_wallet || '0.00'),
          closingWallet: String(data.user.closing_wallet || '0.00'),
        };
        
        setUser(loggedInUser);
        await AsyncStorage.setItem('@easylife_user', JSON.stringify(loggedInUser));
        return true;
      }
      return false;
    } catch (error) {
      console.error("Login Error:", error);
      return false;
    }
  };

  const logout = async () => {
    setUser(null);
    await AsyncStorage.removeItem('@easylife_user');
  };

  const value = useMemo(() => ({ user, isLoading, login, logout }), [user, isLoading]);

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error('useAuth must be used within AuthProvider');
  return ctx;
}