import React, { useState } from "react";
import {
  View,
  Text,
  StyleSheet,
  TextInput,
  Pressable,
  ActivityIndicator,
  Platform,
  KeyboardAvoidingView,
  ScrollView,
  Image,
} from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { LinearGradient } from "expo-linear-gradient";
import * as Haptics from "expo-haptics";
import { Ionicons } from "@expo/vector-icons";
import { useAuth } from "@/context/auth";
import C, { BRAND } from "@/constants/colors";

// BRAND_COLORS array directly for the stripe
const BRAND_COLORS = ["#00B4D8", "#7209B7", "#F72585"];

export default function LoginScreen() {
  const insets = useSafeAreaInsets();
  const { login } = useAuth();
  const [userId, setUserId] = useState("");
  const [password, setPassword] = useState("");
  const [showPass, setShowPass] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const handleLogin = async () => {
    if (!userId.trim() || !password.trim()) {
      setError("Please enter your Member ID and Password");
      return;
    }
    setError("");
    setLoading(true);
    
    // Haptic feedback for tactile feel
    await Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
    
    const success = await login(userId.trim(), password);
    
    if (!success) {
      setError("Invalid Member ID or Password. Please try again.");
      await Haptics.notificationAsync(Haptics.NotificationFeedbackType.Error);
    }
    setLoading(false);
  };

  const topPad = insets.top + (Platform.OS === "web" ? 67 : 0);
  const botPad = insets.bottom + (Platform.OS === "web" ? 34 : 0);

  return (
    <View style={styles.screen}>
      <KeyboardAvoidingView
        style={{ flex: 1 }}
        behavior={Platform.OS === "ios" ? "padding" : "height"}
      >
        <ScrollView
          contentContainerStyle={[
            styles.container,
            { paddingTop: topPad + 24, paddingBottom: botPad + 32 },
          ]}
          keyboardShouldPersistTaps="handled"
          showsVerticalScrollIndicator={false}
        >
          {/* Logo Section */}
          <View style={styles.logoSection}>
            <Image
              source={require("../assets/images/easylife-logo.png")}
              style={styles.logoImg}
              resizeMode="contain"
            />
            <Text style={styles.brandName}>EasyLife</Text>
            <Text style={styles.brandTagline}>Proud Pakistani Company</Text>

            {/* Corporate color stripe */}
            <View style={styles.colorStripe}>
              {BRAND_COLORS.map((c, i) => (
                <View key={i} style={[styles.stripeBlock, { backgroundColor: c }]} />
              ))}
            </View>
          </View>

          {/* Login Form */}
          <View style={styles.formCard}>
            <Text style={styles.formTitle}>Welcome Back</Text>
            <Text style={styles.formSub}>Sign in with your member ID</Text>

            {/* ID field */}
            <View style={styles.inputWrap}>
              <Ionicons name="id-card-outline" size={20} color={C.TEXT_SECONDARY} style={{ marginRight: 10 }} />
              <TextInput
                style={styles.input}
                placeholder="Member ID"
                placeholderTextColor={C.TEXT_SECONDARY}
                value={userId}
                onChangeText={setUserId}
                keyboardType="number-pad"
                autoCapitalize="none"
                returnKeyType="next"
              />
            </View>

            {/* Password field */}
            <View style={styles.inputWrap}>
              <Ionicons name="lock-closed-outline" size={20} color={C.TEXT_SECONDARY} style={{ marginRight: 10 }} />
              <TextInput
                style={[styles.input, { flex: 1 }]}
                placeholder="Password"
                placeholderTextColor={C.TEXT_SECONDARY}
                value={password}
                onChangeText={setPassword}
                secureTextEntry={!showPass}
                returnKeyType="done"
                onSubmitEditing={handleLogin}
              />
              <Pressable onPress={() => setShowPass(!showPass)} style={{ padding: 4 }}>
                <Ionicons
                  name={showPass ? "eye-off-outline" : "eye-outline"}
                  size={20}
                  color={C.TEXT_SECONDARY}
                />
              </Pressable>
            </View>

            {/* Error Message */}
            {error ? (
              <View style={styles.errorBox}>
                <Ionicons name="alert-circle" size={15} color={C.ERROR} />
                <Text style={styles.errorText}>{error}</Text>
              </View>
            ) : null}

            {/* Login Button */}
            <Pressable
              style={({ pressed }) => [styles.loginBtn, { opacity: pressed ? 0.85 : 1 }]}
              onPress={handleLogin}
              disabled={loading}
            >
              <LinearGradient
                colors={[BRAND.blue, BRAND.purple]}
                start={{ x: 0, y: 0 }}
                end={{ x: 1, y: 0 }}
                style={styles.loginGrad}
              >
                {loading ? (
                  <ActivityIndicator color="#fff" />
                ) : (
                  <Text style={styles.loginText}>Sign In</Text>
                )}
              </LinearGradient>
            </Pressable>
          </View>

          <Text style={styles.footer}>Easylife (SMC-Pvt Ltd)</Text>
        </ScrollView>
      </KeyboardAvoidingView>
    </View>
  );
}

