import React, { useState } from 'react';
import { View, Text, StyleSheet, TextInput, Pressable, ScrollView, Linking } from 'react-native';
import { LinearGradient } from 'expo-linear-gradient';
import { Ionicons } from '@expo/vector-icons';
import C from '@/constants/colors';

export default function RegisterMember() {
  const [form, setForm] = useState({ name: '', phone: '', sponsorId: '' });
  const hasSponsor = form.sponsorId.trim().length > 2;

  const handleVerify = () => {
    if (!form.name || !form.phone) {
      alert("Please enter Name and WhatsApp number");
      return;
    }
    const msg = `Salam EasyLife! I am ${form.name}. Phone: ${form.phone}. Sponsor: ${form.sponsorId || 'Direct'}. Please verify my account for the 25% discount.`;
    Linking.openURL(`https://wa.me/message/BZPN5GMP7ZYEH1?text=${encodeURIComponent(msg)}`); 
  };

  return (
    <ScrollView style={styles.container} contentContainerStyle={{ paddingTop: 60, paddingBottom: 100 }}>
      <Text style={styles.title}>Join EasyLife</Text>
      <Text style={styles.subtitle}>Proud Pakistani Company Registration</Text>

      <View style={styles.card}>
        <TextInput style={styles.input} placeholder="Full Name" placeholderTextColor={C.TEXT_SECONDARY} value={form.name} onChangeText={(v) => setForm({...form, name: v})} />
        <TextInput style={styles.input} placeholder="WhatsApp Number" keyboardType="phone-pad" placeholderTextColor={C.TEXT_SECONDARY} value={form.phone} onChangeText={(v) => setForm({...form, phone: v})} />
        <TextInput style={styles.input} placeholder="Sponsor ID (Optional)" placeholderTextColor={C.TEXT_SECONDARY} value={form.sponsorId} onChangeText={(v) => setForm({...form, sponsorId: v})} />

        {hasSponsor && (
          <View style={styles.discountBanner}>
            <Ionicons name="star" size={16} color="#FFD700" />
            <Text style={styles.discountTxt}>25% DISCOUNT ACTIVATED!</Text>
          </View>
        )}

        <Pressable onPress={handleVerify} style={styles.btn}>
          <LinearGradient colors={['#25D366', '#128C7E']} style={styles.grad}>
            <Ionicons name="logo-whatsapp" size={20} color="#fff" style={{marginRight: 10}} />
            <Text style={styles.btnText}>Verify on WhatsApp</Text>
          </LinearGradient>
        </Pressable>
      </View>
    </ScrollView>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, backgroundColor: C.BLACK, padding: 20 },
  title: { fontSize: 32, color: C.TEXT, fontWeight: 'bold' },
  subtitle: { color: C.TEXT_SECONDARY, marginBottom: 30 },
  card: { backgroundColor: C.CARD, padding: 25, borderRadius: 25, gap: 15, borderWidth: 1, borderColor: C.BORDER },
  input: { backgroundColor: C.BLACK, color: C.TEXT, padding: 15, borderRadius: 15, borderWidth: 1, borderColor: C.BORDER },
  discountBanner: { flexDirection: 'row', alignItems: 'center', gap: 8, backgroundColor: 'rgba(255, 215, 0, 0.1)', padding: 12, borderRadius: 12, borderWidth: 1, borderColor: '#FFD700' },
  discountTxt: { color: '#FFD700', fontSize: 12, fontWeight: 'bold' },
  btn: { borderRadius: 15, overflow: 'hidden', marginTop: 10 },
  grad: { padding: 18, flexDirection: 'row', alignItems: 'center', justifyContent: 'center' },
  btnText: { color: '#fff', fontWeight: 'bold', fontSize: 16 }
});